arguments.file_text:
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Returns a greeting for the given name.")]
    public static string Greet(string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime() =>
        $"Current UTC time: {DateTime.UtcNow:O}";
}

using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigResourceProvider
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResource("config://app", Name = "Application Configuration",
        Description = "Returns the current application configuration as JSON.",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource("config://app/features", Name = "Feature Flags",
        Description = "Returns the current feature flag settings.",
        MimeType = "application/json")]
    public static string GetFeatureFlags()
    {
        return JsonSerializer.Serialize(AppConfig["features"], new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

